28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final AddressNormalizer addressNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 AddressNormalizer addressNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.addressNormalizer = addressNormalizer;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = addressNormalizer.normalize(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        LocalDate effectiveDate = owner.getRegistrationDate() != null
129	            ? owner.getRegistrationDate() : LocalDate.now();
130	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
131	        if (isDailyLimitReached(owner.getRegistrationDate())) {
132	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
133	        }
134	        if (isTelephoneInUse(telephone)) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        if (isEmailInUse(owner.getEmail())) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
141	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
142	            return new ResponseEntity<>(HttpStatus.CONFLICT);
143	        }
144	        if (sharesHousehold) {
145	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
146	        }
147	        if (isCityAtCapacity(owner.getCity())) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
151	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
152	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
153	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
154	        this.clinicService.saveOwner(owner);
155	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
156	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    /**
164	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
165	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
166	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
167	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
168	     */
169	    private String nextCustomerCode(String city, String lastName) {
170	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
171	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
172	        int sequence = (int) this.clinicService.findAllOwners().stream()
173	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
174	            .count() + 1;
175	        return String.format("%s-%s-%04d", city3, last3, sequence);
176	    }
177	
178	    /**
179	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
180	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
181	     * (business-day) registration date of the owner being created, so owners are counted per
182	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
183	     */
184	    private boolean isDailyLimitReached(LocalDate day) {
185	        long count = this.clinicService.findAllOwners().stream()
186	            .filter(existing -> day.equals(existing.getRegistrationDate()))
187	            .count();
188	        return count >= 100;
189	    }
190	
191	    /**
192	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
193	     * more than 80 owners have already been created for the given business day. Counts the owners
194	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
195	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
196	     * warning.
197	     */
198	    private boolean isBulkSignup(LocalDate day) {
199	        long count = this.clinicService.findAllOwners().stream()
200	            .filter(existing -> day.equals(existing.getRegistrationDate()))
201	            .count();
202	        return count > 80;
203	    }
204	
205	    /**
206	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
207	     * advance it to the following Monday; a weekday is returned unchanged.
208	     */
209	    private LocalDate toBusinessDay(LocalDate date) {
210	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
211	            date = date.plusDays(1);
212	        }
213	        return date;
214	    }
215	
216	    /**
217	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
218	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
219	     */
220	    private boolean isCityAtCapacity(String city) {
221	        long count = this.clinicService.findAllOwners().stream()
222	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
223	            .count();
224	        return count >= 50;
225	    }
226	
227	    /**
228	     * The number of existing owners that already share the given firstName and lastName,
229	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
230	     * whitespace runs collapsed). Counted over the owners present before this create.
231	     */
232	    private int namesakeCount(String firstName, String lastName) {
233	        String candidateFirstName = normalizeName(firstName);
234	        String candidateLastName = normalizeName(lastName);
235	        return (int) this.clinicService.findAllOwners().stream()
236	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
237	                && normalizeName(existing.getLastName()).equals(candidateLastName))
238	            .count();
239	    }
240	
241	    /**
242	     * The number of members in this owner's household after this create: the count of existing
243	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
244	     * created. An owner with no household ({@code householdId == null}) is a household of one.
245	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
246	     * does not depend on the order in which household members were created.
247	     */
248	    private int householdSize(String householdId) {
249	        if (householdId == null) {
250	            return 1;
251	        }
252	        long existing = this.clinicService.findAllOwners().stream()
253	            .filter(other -> householdId.equals(other.getHouseholdId()))
254	            .count();
255	        return (int) existing + 1;
256	    }
257	
258	    /**
259	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
260	     * cannot form a valid E.164 number.
261	     *
262	     * <p>A leading '+' and country code are kept when present; otherwise country code
263	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
264	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
265	     * carry 8 to 15 digits after the '+'.
266	     */
267	    private String toE164(String telephone) {
268	        if (telephone == null) {
269	            return null;
270	        }
271	        boolean hasCountryCode = telephone.trim().startsWith("+");
272	        String digits = telephone.replaceAll("\\D", "");
273	        String e164;
274	        if (hasCountryCode) {
275	            e164 = digits;
276	        } else {
277	            if (digits.startsWith("0")) {
278	                digits = digits.substring(1);
279	            }
280	            e164 = "61" + digits;
281	        }
282	        if (e164.length() < 8 || e164.length() > 15) {
283	            return null;
284	        }
285	        return "+" + e164;
286	    }
287	
288	    /**
289	     * Whether any existing owner already holds the given telephone number. Both the
290	     * candidate and each stored number are compared in E.164 form, so the check does not
291	     * depend on how each was originally formatted.
292	     */
293	    private boolean isTelephoneInUse(String telephone) {
294	        return this.clinicService.findAllOwners().stream()
295	            .map(Owner::getTelephone)
296	            .filter(Objects::nonNull)
297	            .map(this::toE164)
298	            .filter(Objects::nonNull)
299	            .anyMatch(telephone::equals);
300	    }
301	
302	    /**
303	     * Whether any existing owner already holds the given email address, compared case-insensitively
304	     * (by lower-casing both the candidate and each stored value). A null or empty candidate email is
305	     * never considered in use, so owners without an email do not collide. When true, the new owner
306	     * must be rejected with {@code 409 Conflict}.
307	     */
308	    private boolean isEmailInUse(String email) {
309	        if (email == null || email.isEmpty()) {
310	            return false;
311	        }
312	        String candidate = email.toLowerCase();
313	        return this.clinicService.findAllOwners().stream()
314	            .map(Owner::getEmail)
315	            .filter(Objects::nonNull)
316	            .map(String::toLowerCase)
317	            .anyMatch(candidate::equals);
318	    }
319	
320	    /**
321	     * Whether any existing owner already shares a household with the candidate, i.e. has both
322	     * the same lastName and the same address. Both fields are compared case-insensitively and
323	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
324	     * trimmed), so the check does not depend on casing or spacing.
325	     */
326	    private boolean isHouseholdInUse(String lastName, String address) {
327	        String candidateLastName = normalizeName(lastName);
328	        String candidateAddress = addressNormalizer.normalize(address);
329	        return this.clinicService.findAllOwners().stream()
330	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
331	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
332	    }
333	
334	    /**
335	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
336	     * to a single space and lower-case. A null value normalizes to the empty string.
337	     */
338	    private String normalizeName(String value) {
339	        if (value == null) {
340	            return "";
341	        }
342	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
343	    }
344	
345	    /**
346	     * A stable shared identifier for the household formed by a given lastName and address.
347	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
348	     * lastName and address, so every owner sharing the same household is assigned the same
349	     * value regardless of the order in which they are created. Formatted as the first 12
350	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
351	     */
352	    private String householdId(String lastName, String address) {
353	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
354	        try {
355	            byte[] digest = MessageDigest.getInstance("SHA-256")
356	                .digest(key.getBytes(StandardCharsets.UTF_8));
357	            StringBuilder sb = new StringBuilder(digest.length * 2);
358	            for (byte b : digest) {
359	                sb.append(String.format("%02x", b));
360	            }
361	            return sb.substring(0, 12).toUpperCase();
362	        }
363	        catch (NoSuchAlgorithmException e) {
364	            throw new IllegalStateException("SHA-256 not available", e);
365	        }
366	    }
367	
368	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
369	    @Override
370	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
371	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
372	        if (currentOwner == null) {
373	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
374	        }
375	        currentOwner.setAddress(ownerFieldsDto.getAddress());
376	        currentOwner.setCity(ownerFieldsDto.getCity());
377	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
378	        currentOwner.setLastName(ownerFieldsDto.getLastName());
379	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
380	        this.clinicService.saveOwner(currentOwner);
381	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
382	    }
383	
384	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
385	    @Transactional
386	    @Override
387	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
388	        Owner owner = this.clinicService.findOwnerById(ownerId);
389	        if (owner == null) {
390	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	        }
392	        this.clinicService.deleteOwner(owner);
393	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
394	    }
395	
396	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
397	    @Override
398	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
399	        Owner owner = this.clinicService.findOwnerById(ownerId);
400	        if (owner == null) {
401	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
402	        }
403	        HttpHeaders headers = new HttpHeaders();
404	        Pet pet = petMapper.toPet(petFieldsDto);
405	        owner.setId(ownerId);
406	        pet.setOwner(owner);
407	        pet.getType().setName(null);
408	        this.clinicService.savePet(pet);
409	        PetDto petDto = petMapper.toPetDto(pet);
410	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
411	            .buildAndExpand(pet.getId()).toUri());
412	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
418	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
419	        if (currentOwner != null) {
420	            Pet currentPet = this.clinicService.findPetById(petId);
421	            if (currentPet != null) {
422	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
423	                currentPet.setName(petFieldsDto.getName());
424	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
425	                this.clinicService.savePet(currentPet);
426	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
427	            }
428	        }
429	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
430	    }
431	
432	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
433	    @Override
434	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
435	        HttpHeaders headers = new HttpHeaders();
436	        Visit visit = visitMapper.toVisit(visitFieldsDto);
437	        Pet pet = new Pet();
438	        pet.setId(petId);
439	        visit.setPet(pet);
440	        this.clinicService.saveVisit(visit);
441	        VisitDto visitDto = visitMapper.toVisitDto(visit);
442	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
443	            .buildAndExpand(visit.getId()).toUri());
444	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
445	    }
446	
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
451	        Owner owner = this.clinicService.findOwnerById(ownerId);
452	        if (owner != null) {
453	            Pet pet = owner.getPet(petId);
454	            if (pet != null) {
455	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
456	            }
457	        }
458	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
459	    }
460	}
